//! A downstream crate that depends only on `strands` and `tokio`, compiled under a strict lint
//! profile, so code generated by `#[tool]`, `#[tools]` and `tool_list!` stays warning-free.

#![deny(
    warnings,
    missing_docs,
    clippy::pedantic,
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::allow_attributes_without_reason
)]

use std::sync::Arc;

use strands::{ToolContext, ToolError, ToolSource, tool, tool_list, tools};

/// Get the current weather for a city.
///
/// # Errors
///
/// Never; the signature shows the fallible form.
#[tool]
pub async fn get_weather(
    /// City name, for example "Seattle".
    city: String,
    /// Unit, `celsius` unless given.
    unit: Option<String>,
) -> Result<String, ToolError> {
    tokio::task::yield_now().await;
    Ok(format!(
        "Sunny in {city} ({})",
        unit.unwrap_or_else(|| "celsius".to_owned())
    ))
}

/// Ask the user before deleting a file.
///
/// # Errors
///
/// The `confirm` interrupt until the user answers.
#[tool(name = "delete-file")]
pub fn delete_file(#[tool(context)] ctx: &ToolContext, path: String) -> Result<String, ToolError> {
    let answer = ctx.interrupt("confirm")?;
    Ok(format!("{path}: {answer}"))
}

/// Count the words of a text.
#[tool]
#[must_use]
pub fn count_words(text: String) -> usize {
    text.split_whitespace().count()
}

/// A product inventory.
pub struct Inventory {
    stock: u32,
}

impl Inventory {
    /// An inventory holding `stock` of every product.
    #[must_use]
    pub fn new(stock: u32) -> Self {
        Self { stock }
    }
}

#[tools]
impl Inventory {
    /// Look up stock for a product.
    ///
    /// # Errors
    ///
    /// When the app state's `region` isn't a string.
    #[tool]
    pub async fn check_stock(
        &self,
        #[tool(context)] ctx: &ToolContext,
        /// The product id.
        sku: String,
    ) -> Result<u32, ToolError> {
        let region: Option<String> = ctx.agent().app_state().get("region")?;
        tokio::task::yield_now().await;
        Ok(if sku.is_empty() || region.is_none() {
            0
        } else {
            self.stock
        })
    }

    /// Restock a product.
    #[tool]
    #[must_use]
    pub fn restock(&self, amount: u32) -> u32 {
        self.stock.saturating_add(amount)
    }
}

/// Every tool of this crate.
#[must_use]
pub fn all_tools(inventory: &Arc<Inventory>) -> Vec<ToolSource> {
    let mut tools = tool_list![GetWeather, DeleteFile, CountWords];
    tools.extend(inventory.tools());
    tools
}
